LogicDefinition.ScriptText:
#load "reference"
using System;

//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//                                                                                                          //
//    Logik:           GetCurrentTime                                                                       //
//                                                                                                          //
//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//
//    Datum            Version        Autor            Beschreibung
//
//    28.05.2025       1.4.4          Greif            Header integriert
//    04.12.2025       1.4.6          Egg              Code optimiert    
//
//============================================================================================================
//
//    SW-Standard      Geprüft        Prüfer           Allgemeine Informationen
//                     
//    FEE              x              Greif            Ausgabe von Datum und Zeit in konfigurierbarem Format
/*
//============================================================================================================
//
//    Beschreibung:
//
//    Die Logik gibt das aktuelle Datum und Zeit aus.
//    Beides kann mit den Faktoren (AddX) addiert und ausgeben werden.
//    Die Anzeige erfolgt im Format des Parameters (Format), ist darin nichts parametriert
//    wird das Standardformat (z.B. 5/27/2025 3:25:35 PM) ausgegeben.
//    Beispiel Format: dd-MM-yyyy HH:mm:ss
//
//============================================================================================================
//
//    Voraussetzung/Benutzte Slots:
//
//    Format darf nicht "0" sein!
//    Beispiel Format: dd-MM-yyyy HH:mm:ss
//
//    Input Slot Values
//    Format            =   String, Zeit Ausgabeformat
//    AddYears          =   DInt, Anzahl Jahre
//    AddMonths         =   DInt, Anzahl Monate
//    AddDays           =   DInt, Anzahl Tage
//    AddHours          =   DInt, Anzahl Stunden
//    AddMinutes        =   DInt, Anzahl Minuten
//    AddSeconds        =   DInt, Anzahl Sekunden 
//
//    Output Slot Values
//    Time              =   String, Ausgabe von Datum und Zeit
//    Time_Manipulated  =   String, verrechnete Ausgabe von Datum und Zeit 
//
//============================================================================================================
*/
//////////////////////////////////////////////////////////////////////////////////////////////////////////////

#region Variablen initialisieren
//============================================================================================================
// V A R I A B L E N    I N I T I A L I S I E R E N
//============================================================================================================

// Time Variablen initialisieren
DateTime time = DateTime.Now;
DateTime timeManipulated = time;

#endregion

#region Datum und Zeit manipulieren
//============================================================================================================
// D A T U M    U N D    Z E I T    M A N I P U L I E R E N
//============================================================================================================

timeManipulated = timeManipulated
    .AddYears(AddYears)
    .AddMonths(AddMonths)
    .AddDays(AddDays)
    .AddHours(AddHours)
    .AddMinutes(AddMinutes)
    .AddSeconds(AddSeconds);

#endregion

#region Datum und Zeit ausgeben
//============================================================================================================
// D A T U M    U N D    Z E I T    A U S G E B E N
//============================================================================================================

// Wenn kein Format angegebn, Standardformat verwenden
if(String.IsNullOrWhiteSpace(Format))
{
    Time = time.ToString();
    Time_Manipulated = timeManipulated.ToString();
}
else
{
    try
    {
        Time = time.ToString(Format);
        Time_Manipulated = timeManipulated.ToString(Format);
    }
    catch
    {
        Time = "Invalid Format";
        Time_Manipulated = "Invalid Format";
    }

}

#endregion
